effect.shader:
float gmHash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
void main(){
  vec2 baseUv = acScreenNorm;
  vec4 origin = texture2DCv(inputImg.texture, baseUv);
  float t = floor(acTime * speed);
  float row = floor(baseUv.y * rows);
  float r1 = gmHash(vec2(row, t));
  float r2 = gmHash(vec2(row * 3.7, t + 5.1));
  float active = step(1.0 - chance, r1);
  float dropped = step(1.0 - dropouts * chance, gmHash(vec2(row * 7.3, t + 11.0)));
  vec2 uv = baseUv;
  uv.x += (r2 - 0.5) * 2.0 * shift * active * mixAmt;
  float split = shift * 0.10 * active * mixAmt;
  vec4 sr = texture2DCv(inputImg.texture, uv + vec2(split, 0.0));
  vec4 sg = texture2DCv(inputImg.texture, uv);
  vec4 sb = texture2DCv(inputImg.texture, uv - vec2(split, 0.0));
  float a = max(sg.a, 1e-4);
  vec3 broken = vec3(sr.r / max(sr.a, 1e-4), sg.g / max(sg.a, 1e-4), sb.b / max(sb.a, 1e-4));
  broken = mix(broken, broken * vec3(1.55, 0.62, 1.28), active * 0.72);
  broken *= 1.0 - dropped * 0.70;
  vec4 outSrc = vec4(clamp(broken, 0.0, 1.0) * a, a);
  gl_FragColor = mix(origin, outSrc, mixAmt);
}
